CREATE TABLE IF NOT EXISTS studios (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190),address TEXT,settings JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('Admin','Staff','Trainer','Member') NOT NULL DEFAULT 'Member',branch_ids JSON,member_id INT NULL,contact VARCHAR(50),deleted_at DATETIME,UNIQUE(id,studio_id),FOREIGN KEY(studio_id) REFERENCES studios(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS branches (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,name VARCHAR(150) NOT NULL,address TEXT,contact VARCHAR(50),email VARCHAR(190),opening_time TIME DEFAULT '06:00:00',closing_time TIME DEFAULT '22:00:00',is_main BOOLEAN DEFAULT FALSE,deleted_at DATETIME,UNIQUE(id,studio_id),FOREIGN KEY(studio_id) REFERENCES studios(id));
CREATE TABLE IF NOT EXISTS rooms (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NOT NULL,name VARCHAR(150) NOT NULL,capacity INT NOT NULL,rental_eligible BOOLEAN DEFAULT TRUE,hourly_rate DECIMAL(12,2) DEFAULT 1500,description TEXT,deleted_at DATETIME,UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS members (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL,contact VARCHAR(50),gender VARCHAR(30),birth_date DATE,address TEXT,status VARCHAR(30) DEFAULT 'Active',joined_at DATE NOT NULL,deleted_at DATETIME,UNIQUE(id,studio_id),UNIQUE(studio_id,email),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id));
CREATE TABLE IF NOT EXISTS trainers (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) DEFAULT '',email VARCHAR(190),contact VARCHAR(50),specialization TEXT,bio TEXT,status VARCHAR(30) DEFAULT 'Active',deleted_at DATETIME,UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id));
CREATE TABLE IF NOT EXISTS plans (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,plan_type VARCHAR(50) DEFAULT 'Class Package',duration INT NOT NULL,credits INT NULL,price DECIMAL(12,2) NOT NULL,branch_ids JSON,class_ids JSON,freeze_allowed BOOLEAN DEFAULT TRUE,max_freeze_days INT DEFAULT 14,status VARCHAR(30) DEFAULT 'Active',deleted_at DATETIME,UNIQUE(id,studio_id),CHECK(duration>0),CHECK(credits IS NULL OR credits>0),CHECK(price>=0));
CREATE TABLE IF NOT EXISTS memberships (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,member_id INT NOT NULL,plan_id INT NOT NULL,start_at DATE NOT NULL,end_at DATE NOT NULL,available INT NULL,reserved INT NOT NULL DEFAULT 0,used INT NOT NULL DEFAULT 0,price DECIMAL(12,2) NOT NULL,terms JSON NOT NULL,status VARCHAR(30) DEFAULT 'Active',freeze_start DATE,freeze_end DATE,freeze_days INT DEFAULT 0,UNIQUE(id,studio_id),FOREIGN KEY(member_id,studio_id) REFERENCES members(id,studio_id),FOREIGN KEY(plan_id,studio_id) REFERENCES plans(id,studio_id),CHECK(available IS NULL OR available>=0),CHECK(reserved>=0),CHECK(used>=0));
CREATE TABLE IF NOT EXISTS classes (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,name VARCHAR(150) NOT NULL,type VARCHAR(80) NOT NULL,difficulty VARCHAR(50) DEFAULT 'All levels',duration INT DEFAULT 60,capacity INT DEFAULT 12,price DECIMAL(12,2) DEFAULT 700,description TEXT,status VARCHAR(30) DEFAULT 'Active',deleted_at DATETIME,UNIQUE(id,studio_id),CHECK(duration>0),CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS schedules (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NOT NULL,room_id INT NOT NULL,trainer_id INT NOT NULL,class_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,capacity INT NOT NULL,status VARCHAR(30) DEFAULT 'Published',series_ref VARCHAR(64),UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),FOREIGN KEY(room_id,studio_id) REFERENCES rooms(id,studio_id),FOREIGN KEY(trainer_id,studio_id) REFERENCES trainers(id,studio_id),FOREIGN KEY(class_id,studio_id) REFERENCES classes(id,studio_id),CHECK(end_at>start_at),CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS bookings (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,schedule_id INT NOT NULL,member_id INT NOT NULL,membership_id INT NOT NULL,status VARCHAR(30) DEFAULT 'Confirmed',booked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,cancelled_at DATETIME,reason TEXT,checkin_hash CHAR(64),checkin_expires DATETIME,active_key VARCHAR(100) GENERATED ALWAYS AS (CASE WHEN status IN ('Confirmed','Waitlisted','Present','Late','No-Show') THEN CONCAT(member_id,':',schedule_id) ELSE NULL END) STORED,UNIQUE(active_key),UNIQUE(id,studio_id),FOREIGN KEY(schedule_id,studio_id) REFERENCES schedules(id,studio_id),FOREIGN KEY(member_id,studio_id) REFERENCES members(id,studio_id),FOREIGN KEY(membership_id,studio_id) REFERENCES memberships(id,studio_id));
CREATE TABLE IF NOT EXISTS credit_transactions (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,membership_id INT NOT NULL,booking_id INT NULL,type VARCHAR(30) NOT NULL,delta INT NOT NULL,notes TEXT,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(membership_id,studio_id) REFERENCES memberships(id,studio_id),FOREIGN KEY(booking_id,studio_id) REFERENCES bookings(id,studio_id),FOREIGN KEY(user_id,studio_id) REFERENCES users(id,studio_id));
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,booking_id INT NOT NULL UNIQUE,status VARCHAR(30) NOT NULL,checked_in_at DATETIME NOT NULL,user_id INT NOT NULL,FOREIGN KEY(booking_id,studio_id) REFERENCES bookings(id,studio_id));
CREATE TABLE IF NOT EXISTS rentals (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NOT NULL,room_id INT NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190),contact VARCHAR(50),purpose TEXT,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,attendees INT DEFAULT 1,hourly_rate DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,deposit DECIMAL(12,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'Confirmed',whole_venue BOOLEAN DEFAULT FALSE,UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),FOREIGN KEY(room_id,studio_id) REFERENCES rooms(id,studio_id),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS room_blocks (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,room_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,reason TEXT,FOREIGN KEY(room_id,studio_id) REFERENCES rooms(id,studio_id));
CREATE TABLE IF NOT EXISTS retreats (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NOT NULL,title VARCHAR(190) NOT NULL,description TEXT,category VARCHAR(80) DEFAULT 'Wellness',venue VARCHAR(190),start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,capacity INT NOT NULL,fee DECIMAL(12,2) NOT NULL,registration_close DATETIME NOT NULL,status VARCHAR(30) DEFAULT 'Published',itinerary JSON,deleted_at DATETIME,UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),CHECK(capacity>0),CHECK(fee>=0),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS retreat_registrations (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,retreat_id INT NOT NULL,member_id INT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,contact VARCHAR(50),seats INT DEFAULT 1,total DECIMAL(12,2) NOT NULL,status VARCHAR(30) DEFAULT 'Confirmed',checked_in_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,studio_id),FOREIGN KEY(retreat_id,studio_id) REFERENCES retreats(id,studio_id),FOREIGN KEY(member_id,studio_id) REFERENCES members(id,studio_id),CHECK(seats>0));
CREATE TABLE IF NOT EXISTS invoices (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,branch_id INT NULL,member_id INT NULL,customer VARCHAR(150) NOT NULL,type VARCHAR(50) NOT NULL,reference_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) DEFAULT 'Pending',snapshot JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),FOREIGN KEY(member_id,studio_id) REFERENCES members(id,studio_id));
CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,invoice_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(50) NOT NULL,reference VARCHAR(190),status VARCHAR(30) DEFAULT 'Paid',user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,studio_id),FOREIGN KEY(invoice_id,studio_id) REFERENCES invoices(id,studio_id),CHECK(amount>0));
CREATE TABLE IF NOT EXISTS refunds (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,payment_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,reason TEXT NOT NULL,status VARCHAR(30) DEFAULT 'Processed',user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(payment_id,studio_id) REFERENCES payments(id,studio_id),CHECK(amount>0));
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,member_id INT NULL,title VARCHAR(190) NOT NULL,message TEXT NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_logs (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,user_id INT NOT NULL,module VARCHAR(80) NOT NULL,action VARCHAR(190) NOT NULL,reference VARCHAR(190),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inquiries (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,studio_name VARCHAR(150),contact VARCHAR(50),message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_resets (token_hash CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME);
CREATE TABLE IF NOT EXISTS import_jobs (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,user_id INT NOT NULL,type VARCHAR(50),row_count INT,status VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trainer_availability (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,trainer_id INT NOT NULL,branch_id INT NOT NULL,day_of_week INT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(trainer_id,studio_id) REFERENCES trainers(id,studio_id),FOREIGN KEY(branch_id,studio_id) REFERENCES branches(id,studio_id),CHECK(day_of_week BETWEEN 0 AND 6),CHECK(end_time>start_time));
CREATE TABLE IF NOT EXISTS trainer_unavailability (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,trainer_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,reason TEXT,FOREIGN KEY(trainer_id,studio_id) REFERENCES trainers(id,studio_id),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS notification_rules (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,event_type VARCHAR(80) NOT NULL,lead_minutes INT DEFAULT 60,channel VARCHAR(30) DEFAULT 'In-app',template TEXT NOT NULL,enabled BOOLEAN DEFAULT TRUE,UNIQUE(studio_id,event_type));
CREATE TABLE IF NOT EXISTS retreat_itinerary (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,retreat_id INT NOT NULL,room_id INT NULL,trainer_id INT NULL,title VARCHAR(190) NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,location VARCHAR(190),FOREIGN KEY(retreat_id,studio_id) REFERENCES retreats(id,studio_id),FOREIGN KEY(room_id,studio_id) REFERENCES rooms(id,studio_id),FOREIGN KEY(trainer_id,studio_id) REFERENCES trainers(id,studio_id),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS reminder_deliveries (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,rule_id INT NOT NULL,event_ref VARCHAR(190) NOT NULL,member_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(rule_id,event_ref,member_id));
CREATE TABLE IF NOT EXISTS retreat_checkins (id INT AUTO_INCREMENT PRIMARY KEY,studio_id INT NOT NULL,registration_id INT NOT NULL,seat_number INT NOT NULL,participant_name VARCHAR(190) NOT NULL,checked_in_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,user_id INT NOT NULL,UNIQUE(registration_id,seat_number),FOREIGN KEY(registration_id,studio_id) REFERENCES retreat_registrations(id,studio_id));
